/bin/bash -lc "mkdir -p /output/raw /output/code /output/logs && (command -v python3; python3 - <<'PY'
import importlib.util
for x in ['pandas','numpy','statsmodels','scipy','requests']:
 print(x, bool(importlib.util.find_spec(x)))
PY
) && curl --fail --silent --show-error --location --output /output/raw/owid-covid-data.csv https://covid.ourworldindata.org/data/owid-covid-data.csv && curl --fail --silent --show-error --location --output /output/raw/wb_pm25.json 'https://api.worldbank.org/v2/country/all/indicator/EN.ATM.PM25.MC.M3?format=json&per_page=20000' && curl --fail --silent --show-error --location --output /output/raw/wb_physicians.json 'https://api.worldbank.org/v2/country/all/indicator/SH.MED.PHYS.ZS?format=json&per_page=20000' && curl --fail --silent --show-error --location --output /output/raw/wb_beds.json 'https://api.worldbank.org/v2/country/all/indicator/SH.MED.BEDS.ZS?format=json&per_page=20000' && curl --fail --silent --show-error --location --output /output/raw/wb_elderly.json 'https://api.worldbank.org/v2/country/all/indicator/SP.POP.65UP.TO.ZS?format=json&per_page=20000' && curl --fail --silent --show-error --location --output /output/raw/wb_density.json 'https://api.worldbank.org/v2/country/all/indicator/EN.POP.DNST?format=json&per_page=20000' && curl --fail --silent --show-error --location --output /output/raw/wb_gdp.json 'https://api.worldbank.org/v2/country/all/indicator/NY.GDP.PCAP.CD?format=json&per_page=20000' && sha256sum /output/raw/*"

